                                THEN
                                    expected_token_value = SSP | BUSY_BIT (* busy bit - bit position 0 - must be set *)
                                    new_token_value = SSP (* clear the busy bit *)
                                    shadow_stack_lock_cmpxchg8b(SSP, new_token_value, expected_token_value)
